const alert = $json.body;
const timestamp = new Date().toISOString();

const formattedMessage = `🚨 [CYCLONEX EMERGENCY ALERT]\n` +
  `Cyclone: ${alert.cyclone_name || 'Unassigned / Invest Cell'}\n` +
  `Classification: ${alert.classification || 'Severe Cyclone'}\n` +
  `Severity: ${alert.severity || 'WARNING'}\n` +
  `Prototype Risk Index: ${alert.risk_score} / 100 (${alert.risk_level})\n` +
  `Wind Speed: ${alert.wind_speed_kts || alert.wind_speed} kts\n` +
  `Central Pressure: ${alert.pressure_hpa || alert.pressure} hPa\n` +
  `Location: Lat ${alert.latitude}, Lon ${alert.longitude}\n` +
  `Timestamp: ${timestamp}\n` +
  `Notice: Non-operational prototype decision support index.`;

return [{
  json: {
    alert_id: alert.alert_id || 'ALT-' + Date.now(),
    risk_score: alert.risk_score,
    risk_level: alert.risk_level,
    payload_text: formattedMessage,
    channels: ['webhook_dispatch', 'broadcast_dashboard']
  }
}];

const alert = $json.body;
return [{
  json: {
    status: 'ADVISORY_LOGGED',
    message: 'Advisory logged for routine monitoring. Risk score below immediate critical broadcast threshold.',
    risk_score: alert.risk_score
  }
}];
